import { readFile, unlink } from 'node:fs/promises'
import { join } from 'node:path'
import { writeAtomic } from './machine-files.js'
import { openLibrary } from './library.js'
import type { Grant, GrantId, Library, PluginTable } from '@pneuma-base/sdk'

/** A grant's name is also a file name and part of a skill name, so it stays short and plain. */
export const GRANT_NAME = /^[a-z0-9][a-z0-9-]{0,40}$/

/** The agent's local copy of a grant: which library, which grant. Not library state; regenerated by issuing again. */
export type GrantFile = { name: string; library: string; grant: GrantId }

export function grantFilePath(home: string, name: string): string {
  return join(home, 'grants', `${name}.json`)
}

export async function readGrantFile(home: string, name: string): Promise<GrantFile | null> {
  try {
    const raw = JSON.parse(await readFile(grantFilePath(home, name), 'utf8')) as Partial<GrantFile>
    if (typeof raw.library !== 'string' || typeof raw.grant !== 'string') return null
    return { name, library: raw.library, grant: raw.grant }
  } catch {
    return null
  }
}

export async function writeGrantFile(home: string, file: GrantFile): Promise<string> {
  const path = grantFilePath(home, file.name)
  await writeAtomic(path, `${JSON.stringify(file, null, 2)}\n`, join(home, 'grants'))
  return path
}

export async function removeGrantFile(home: string, name: string): Promise<void> {
  await unlink(grantFilePath(home, name)).catch(() => undefined)
}

export type ResolvedGrant =
  | { ok: true; library: Library; grant: Grant }
  | { ok: false; reason: 'no-such-grant' | 'no-library' | 'grant-revoked'; text: string }

/** The gate for `@<name>`: the local grant file, its library, and the grant still present in that library's configuration. */
export async function resolveGrant(home: string, name: string, table: PluginTable): Promise<ResolvedGrant> {
  const file = GRANT_NAME.test(name) ? await readGrantFile(home, name) : null
  if (!file) return { ok: false, reason: 'no-such-grant', text: `本机没有名为 ${name} 的授权（${grantFilePath(home, name)}）` }
  const library = await openLibrary(file.library, table)
  if (!library) return { ok: false, reason: 'no-library', text: `授权 ${name} 指向的资料库不存在：${file.library}` }
  const grant = library.config.grants.find((g) => g.id === file.grant)
  if (!grant) return { ok: false, reason: 'grant-revoked', text: `授权 ${name} 已被所有者撤销` }
  return { ok: true, library, grant }
}
